  static Material seaBasalt,seaCliff,seaSand,seaGrass,seaPlank,seaPlankLight,seaMortar,seaRoof,seaRoofLight,seaLava;
  static void MarinePalette(){Palette();RomanArtPalette();seaBasalt=Paint("Marine Basalt",new Color(.24f,.29f,.32f),.15f);seaCliff=Paint("Marine Weathered Cliff",new Color(.54f,.58f,.51f),.2f);seaSand=Paint("Marine Warm Beach",new Color(.83f,.76f,.54f),.4f);seaGrass=Paint("Marine Patchy Scrub",new Color(.39f,.51f,.28f),.15f);seaPlank=Paint("Marine Aged Planks",new Color(.43f,.30f,.21f),.15f);seaPlankLight=Paint("Marine Sunlit Planks",new Color(.58f,.43f,.29f),.18f);seaMortar=Paint("Marine Lime Mortar",new Color(.69f,.70f,.61f),.2f);seaRoof=Paint("Marine Clay Tiles",new Color(.56f,.24f,.18f),.18f);seaRoofLight=Paint("Marine Worn Tiles",new Color(.69f,.34f,.23f),.18f);seaLava=Paint("Marine Ember Lava",new Color(.95f,.35f,.075f),.85f);}
  static float CoastRadius(int i,int n,int variant){float a=i*Mathf.PI*2/n;return 1+.10f*Mathf.Sin(a*3+variant)+.07f*Mathf.Cos(a*5+variant*.7f)+.035f*Mathf.Sin(a*9);}
  static float MarineGroundHeight(float w,float d,int variant,float x,float z){float a=Mathf.Atan2(z/(d*.5f),x/(w*.5f));float j=1+.10f*Mathf.Sin(a*3+variant)+.07f*Mathf.Cos(a*5+variant*.7f)+.035f*Mathf.Sin(a*9);float r=Mathf.Sqrt(x*x/(w*w*.25f)+z*z/(d*d*.25f))/j;float[] rings={0,.24f,.49f,.68f,.82f,1,1.08f};float[] h={1.3f,1.3f,1.22f,.9f,.44f,-.25f,-.9f};for(int i=0;i<rings.Length-1;i++)if(r<=rings[i+1]){float t=Mathf.InverseLerp(rings[i],rings[i+1],r);float y=Mathf.Lerp(h[i],h[i+1],t);return y+(i==0?0:.11f*Mathf.Sin(a*4+variant)*r);}return -.9f;}
  static void MarineLand(Transform t,float w,float depth,int variant,bool lush=true){
   const int sides=48;float[] rings={0,.24f,.49f,.68f,.82f,1f,1.08f};float[] heights={1.3f,1.3f,1.22f,.9f,.44f,-.25f,-.9f};
   for(int band=0;band<rings.Length-1;band++){var v=new List<Vector3>();var tr=new List<int>();for(int r=0;r<2;r++)for(int i=0;i<=sides;i++){float a=i*Mathf.PI*2/sides,j=CoastRadius(i,sides,variant),radius=rings[band+r];float y=heights[band+r]+(band+r<2?0:.11f*Mathf.Sin(a*4+variant)*radius);v.Add(new Vector3(Mathf.Cos(a)*w*.5f*radius*j,y,Mathf.Sin(a)*depth*.5f*radius*j));}for(int i=0;i<sides;i++){tr.AddRange(new[]{i,i+1,i+sides+1,i+1,i+sides+2,i+sides+1});}MeshObject(t,"Contiguous Eroded Coast Band "+band,v,tr,band<2&&lush?seaGrass:band<4?seaSand:seaCliff);}
   for(int i=0;i<8;i++){float a=i*2.399f+variant,r=.68f+(i%3)*.07f;var p=new Vector3(Mathf.Cos(a)*w*.5f*r,.1f,Mathf.Sin(a)*depth*.5f*r);Lathe(t,"Coastal Strata Boulder",p,new[]{-.5f,.1f,.6f,.9f},new[]{1.2f,1.5f,1.1f,.3f},i%2==0?seaCliff:seaBasalt,7);}
  }
  static void MarineMasonry(Transform t,Vector3 p,float width,float height,float depth,Material wall){Box(t,"Bonded Masonry Core",p+Vector3.up*height*.5f,new Vector3(width,height,depth),wall);for(int row=0;row<Mathf.FloorToInt(height/.46f);row++){float y=.24f+row*.46f;Box(t,"Recessed Mortar Bed",p+new Vector3(0,y,-depth*.5f-.012f),new Vector3(width,.023f,.025f),seaMortar);for(int i=0;i<Mathf.CeilToInt(width/1.2f);i++){float x=-width*.5f+(i+.5f)*1.2f+(row%2)*.45f;if(x>width*.5f-.1f)continue;Box(t,"Staggered Stone Joint",p+new Vector3(x,y+.22f,-depth*.5f-.018f),new Vector3(.025f,.42f,.026f),seaMortar);}}foreach(float side in new[]{-1f,1f})for(float y=.25f;y<height;y+=.5f)Box(t,"Cut Stone Corner Quoin",p+new Vector3(side*(width*.5f-.18f),y,-depth*.5f-.03f),new Vector3(.38f,.28f,.13f),cream);}
  static void MarineRoof(Transform t,Vector3 p,float w,float d,float rise,bool woodRoof=false){
   foreach(float side in new[]{-1f,1f})for(int r=0;r<5;r++){float z=-d*.45f+r*d*.225f;Beam(t,"Load Bearing Roof Rafter",p+new Vector3(side*w*.5f,-.08f,z),p+new Vector3(0,rise-.08f,z),.16f,seaPlank);}
   int rows=Mathf.CeilToInt(d/.42f);for(int side=-1;side<=1;side+=2){float slope=rise/(w*.5f);for(int row=0;row<rows;row++)for(int col=0;col<7;col++){float u=(col+.5f)/7,x=side*u*w*.5f,y=rise*(1-u),z=-d*.5f+(row+.5f)*d/rows;var tile=Box(t,woodRoof?"Overlapping Cedar Shingle":"Individual Overlapping Roof Tile",p+new Vector3(x,y,z),new Vector3(w/14+.055f,.075f,d/rows+.07f),(row+col)%4==0?(woodRoof?seaPlankLight:seaRoofLight):(woodRoof?seaPlank:seaRoof));tile.transform.localRotation=Quaternion.Euler(0,0,-side*Mathf.Atan(slope)*Mathf.Rad2Deg);}}
   Beam(t,"Closed Ridge Cap",p+new Vector3(0,rise,-d*.5f-.1f),p+new Vector3(0,rise,d*.5f+.1f),.17f,woodRoof?seaPlankLight:seaRoofLight);foreach(float z in new[]{-d*.5f,d*.5f}){MeshObject(t,"Closed Triangular Roof Gable",new List<Vector3>{p+new Vector3(-w*.5f,0,z),p+new Vector3(0,rise,z),p+new Vector3(w*.5f,0,z)},new List<int>{0,1,2,2,1,0},seaPlank);}}
  static void MarineWindow(Transform t,Vector3 p,float width=.8f,float height=1.05f){Box(t,"Deep Shadowed Window",p,new Vector3(width,height,.10f),dark);foreach(float side in new[]{-1f,1f}){Box(t,"Window Timber Jamb",p+new Vector3(side*(width*.5f+.055f),0,-.06f),new Vector3(.1f,height+.2f,.14f),seaPlankLight);for(int i=0;i<4;i++)Box(t,"Slatted Window Shutter",p+new Vector3(side*(width*.5f+.25f),-.35f+i*.23f,-.08f),new Vector3(.29f,.16f,.12f),seaPlank);}Box(t,"Projecting Window Sill",p+new Vector3(0,-height*.5f-.1f,-.14f),new Vector3(width+.55f,.16f,.38f),seaCliff);Beam(t,"Window Cross Mullion",p+new Vector3(0,-height*.5f,-.1f),p+new Vector3(0,height*.5f,-.1f),.055f,seaPlankLight);}
  static void MarineShop(Transform t,float w,float h,float d,int kind){
   PlankedPier(t,w+2,d+3);MarineMasonry(t,new Vector3(0,.51f,0),w,h,d,kind==1?blue:kind==2?seaCliff:cream);MarineRoof(t,new Vector3(0,h+.51f,0),w+.7f,d+.8f,1.4f,kind==1);ThemeDoor(t,new Vector3(-w*.25f,.51f,-d*.5f-.05f),1.25f,2.3f);MarineWindow(t,new Vector3(w*.24f,2.45f,-d*.5f-.07f));for(int i=0;i<Mathf.CeilToInt(w/.6f);i++)Box(t,"Shop Timber Fascia",new Vector3(-w*.5f+i*.6f,h+.4f,-d*.5f-.12f),new Vector3(.5f,.22f,.18f),seaPlankLight);
   Beam(t,"Shop Sign Wall Bracket",new Vector3(w*.4f,h-.15f,-d*.5f),new Vector3(w*.4f,h-.15f,-d*.5f-1.3f),.10f,seaPlank);Beam(t,"Sign Chain Supporting Crossbar",new Vector3(w*.4f-.45f,h-.15f,-d*.5f-1.15f),new Vector3(w*.4f+.45f,h-.15f,-d*.5f-1.15f),.09f,seaPlank);Box(t,"Hanging Painted Shop Sign",new Vector3(w*.4f,h-.65f,-d*.5f-1.15f),new Vector3(1.05f,.75f,.12f),kind==2?dark:blue);foreach(float x in new[]{w*.4f-.36f,w*.4f+.36f})Beam(t,"Sign Suspension Chain",new Vector3(x,h-.15f,-d*.5f-1.15f),new Vector3(x,h-.3f,-d*.5f-1.15f),.028f,dark);
  }
  static void SmallFishingBoat(Transform t,Vector3 p,float yaw){var g=new GameObject("Unmanned Planked Fishing Skiff");g.transform.SetParent(t,false);g.transform.localPosition=p;g.transform.localRotation=Quaternion.Euler(0,yaw,0);var r=g.transform;var v=new List<Vector3>();var tr=new List<int>();float[] xs={-3,-2,-.5f,1.3f,2.7f,3.2f};float[] widths={.05f,.8f,1.1f,1,.5f,.02f};for(int i=0;i<xs.Length;i++)v.AddRange(new[]{new Vector3(xs[i],.7f,-widths[i]),new Vector3(xs[i],.7f,widths[i]),new Vector3(xs[i],-.25f,widths[i]*.35f),new Vector3(xs[i],-.25f,-widths[i]*.35f)});for(int i=0;i<xs.Length-1;i++)for(int j=0;j<4;j++){int k=i*4+j,n=i*4+(j+1)%4;tr.AddRange(new[]{k,k+4,n,n,k+4,n+4});}MeshObject(r,"Closed Skiff Hull",v,tr,seaPlank);foreach(float x in new[]{-1.6f,0,1.4f})Box(r,"Skiff Rowing Bench",new Vector3(x,.55f,0),new Vector3(.45f,.15f,1.7f),seaPlankLight);Beam(r,"Fishing Rod",new Vector3(.3f,.4f,0),new Vector3(2.9f,2.6f,-1.5f),.045f,wood);Beam(r,"Fishing Line to Water",new Vector3(2.9f,2.6f,-1.5f),new Vector3(3.3f,-.4f,-1.7f),.012f,cream);foreach(float side in new[]{-1f,1f}){Beam(r,"Resting Oar",new Vector3(-1,.8f,0),new Vector3(1,.8f,side*2.5f),.06f,seaPlankLight);Box(r,"Oar Paddle",new Vector3(1,.8f,side*2.5f),new Vector3(.38f,.1f,.9f),seaPlank);}Box(r,"Fishing Tackle Box",new Vector3(-1,.6f,0),new Vector3(.7f,.5f,.6f),blue);}
  static float MarineVolcanoHeight(float x,float z){float a=Mathf.Atan2(z/.78f,x),r=Mathf.Sqrt(x*x+z*z/(.78f*.78f));float[] rs={12,10,7.8f,5.5f,3.2f,2.8f,1.5f},hs={1,1.6f,4,6.6f,9.1f,8.8f,7.7f};for(int i=0;i<rs.Length;i++){rs[i]*=1+.07f*Mathf.Sin(a*5+i);hs[i]+=.3f*Mathf.Sin(a*3+.5f)*i/6;}for(int i=0;i<rs.Length-1;i++)if(r>=rs[i+1])return Mathf.Lerp(hs[i],hs[i+1],Mathf.InverseLerp(rs[i],rs[i+1],r));return 7.7f;}
  static void MarineVolcano(Transform t){MarineLand(t,44,25,11,false);const int n=40;float[] radius={12,10,7.8f,5.5f,3.2f,2.8f,1.5f};float[] h={1,1.6f,4,6.6f,9.1f,8.8f,7.7f};var v=new List<Vector3>();var tr=new List<int>();for(int r=0;r<radius.Length;r++)for(int i=0;i<n;i++){float a=i*Mathf.PI*2/n;float rad=radius[r]*(1+.07f*Mathf.Sin(a*5+r));v.Add(new Vector3(Mathf.Cos(a)*rad,h[r]+.3f*Mathf.Sin(a*3+.5f)*r/6,Mathf.Sin(a)*rad*.78f));}for(int r=0;r<radius.Length-1;r++)for(int i=0;i<n;i++){int k=r*n+i,j=r*n+(i+1)%n;tr.AddRange(new[]{k,k+n,j,j,k+n,j+n});}MeshObject(t,"Stratified Crater Volcano",v,tr,seaBasalt);Cylinder(t,"Contained Crater Glow",new Vector3(0,7.72f,0),1.52f,.06f,seaLava,24);for(int i=0;i<3;i++){var path=new List<Vector3>{new Vector3(-1+i*.9f,0,-2.1f),new Vector3(-2+i*1.3f,0,-4.2f),new Vector3(-2.5f+i*1.7f,0,-6.2f),new Vector3(-4+i*2,0,-8.4f)};var sampled=new List<Vector3>();for(int k=0;k<path.Count-1;k++)for(int j=0;j<8;j++){var p=Vector3.Lerp(path[k],path[k+1],j/8f);p.y=MarineVolcanoHeight(p.x,p.z)+.015f;sampled.Add(p);}var end=path[path.Count-1];end.y=MarineVolcanoHeight(end.x,end.z)+.015f;sampled.Add(end);Tube(t,"Attached Cooling Lava Seam",sampled,.11f,seaLava,6,.045f);}}
  static void MarineCliffArch(Transform t){
   // A continuous irregular tunnel shell; the opening remains genuinely empty.
   const int n=24;var v=new List<Vector3>();var tr=new List<int>();for(int i=0;i<=n;i++){float a=Mathf.PI*i/n;for(int layer=0;layer<4;layer++){bool outer=layer%2==1;float rx=outer?7.3f+.38f*Mathf.Sin(i*1.9f):4.2f,ry=outer?8.0f+.5f*Mathf.Sin(i*1.3f):5.1f;float z=layer<2?-2.3f:2.3f;v.Add(new Vector3(Mathf.Cos(a)*rx,Mathf.Sin(a)*ry-.35f,z+(outer?.3f*Mathf.Sin(i*2):0)));}}for(int i=0;i<n;i++){int k=i*4,j=k+4;tr.AddRange(new[]{k,k+1,j,k+1,j+1,j,k+2,j+2,k+3,k+3,j+2,j+3,k+1,k+3,j+1,k+3,j+3,j+1,k,j,k+2,k+2,j,j+2});}MeshObject(t,"Eroded Continuous Sea Tunnel",v,tr,seaCliff);foreach(float side in new[]{-1f,1f})for(int i=0;i<5;i++)Lathe(t,"Fractured Cliff Buttress",new Vector3(side*(5.3f+i*.52f),-.8f,(i%2-.5f)*3),new[]{0f,1.2f,3.2f,4.2f+i*.32f},new[]{1.5f,1.8f,1.4f,.3f},i%2==0?seaCliff:seaBasalt,7);for(int i=0;i<6;i++)Box(t,"Exposed Horizontal Strata",new Vector3(-6.2f,.7f+i*.7f,-2.5f),new Vector3(2.1f,.065f,.13f),seaMortar);}
  static void MarineVessel(Transform t,bool admiral){Ship(t);for(int i=0;i<27;i++)Box(t,"Deck Plank Joint",new Vector3(-7.4f+i*.55f,2.66f,0),new Vector3(.022f,.015f,4),seaPlankLight);foreach(float side in new[]{-1f,1f})for(int i=0;i<18;i++){float x=-7+i*.8f;Box(t,"Ship Hull Painted Wale",new Vector3(x,1.65f,side*2.25f),new Vector3(.76f,.16f,.1f),admiral?gold:seaPlankLight);Box(t,"Hull Weathered Plank",new Vector3(x,.95f,side*1.98f),new Vector3(.76f,.12f,.1f),seaPlankLight);}if(admiral){MarineRoof(t,new Vector3(-6.7f,3.85f,0),4.6f,4.8f,1,true);foreach(float z in new[]{-2.25f,2.25f})for(int i=0;i<5;i++)Box(t,"Admiral Stern Gilded Gallery",new Vector3(-8.4f+i*.85f,3.15f,z),new Vector3(.11f,1.2f,.16f),gold);foreach(var r in t.GetComponentsInChildren<MeshRenderer>()){var mats=r.sharedMaterials;for(int j=0;j<mats.Length;j++){if(mats[j]==wood)mats[j]=blue;if(mats[j]==red)mats[j]=blue;}r.sharedMaterials=mats;}}else{foreach(var p in t.GetComponentsInChildren<Transform>())if(p.name=="Wind Caught Banner"){var r=p.GetComponent<Renderer>();if(r)r.sharedMaterial=dark;}}}
