   for(int i=0;i<5;i++){var g=new GameObject("Individual Harbor District "+i);g.transform.SetParent(t,false);g.transform.localPosition=new Vector3(xs[i],1.3f,zs[i]);float w=ws[i],h=hs[i],depth=i==2?5:4;Box(g.transform,"Harbor Ground Foundation",new Vector3(0,-.8f,0),new Vector3(w+.3f,1.6f,depth+.3f),seaCliff);MarineMasonry(g.transform,Vector3.zero,w,h,depth,i==1?seaCliff:i==3?blue:cream);MarineRoof(g.transform,new Vector3(0,h,0),w+.7f,depth+.7f,i==1?2:1.2f,i==2);ThemeDoor(g.transform,new Vector3(0,0,-depth*.5f-.08f),1.1f,1.8f);if(i==0||i==2){MarineWindow(g.transform,new Vector3(-w*.3f,1.8f,-depth*.5f-.1f));MarineWindow(g.transform,new Vector3(w*.3f,1.8f,-depth*.5f-.1f));}else MarineWindow(g.transform,new Vector3(0,h-.9f,-depth*.5f-.1f));if(i==1){Cylinder(g.transform,"Harbor Bell Tower",new Vector3(3,0,.7f),.8f,6.8f,cream,12);Lathe(g.transform,"Harbor Spire",new Vector3(3,6.8f,.7f),new[]{0f,1.6f},new[]{1,.01f},seaRoof,12);}if(i==3)Box(g.transform,"Harbor Chimney",new Vector3(1,h+.9f,1),new Vector3(.6f,1.8f,.7f),seaCliff);}
   foreach(float x in new[]{-15f,9f}){var jetty=new GameObject("Harbor Finger Pier");jetty.transform.SetParent(t,false);jetty.transform.localPosition=new Vector3(x,.1f,-9);PlankedPier(jetty.transform,4,12);Box(t,"Harbor Pier Landing Abutment",new Vector3(x,.5f,-4),new Vector3(4,1.5f,3),seaCliff);}
  }
